<template>
  <QBtn
    unelevated
    :disable="blocked"
    :loading="loading"
    :flat="isFlat"
    :outline="isOutline"
    :round="round"
    :dense="dense"
    :ripple="!blocked"
    :icon="iconOnly && icon ? icon : undefined"
    :to="to || undefined"
    :aria-label="ariaLabel || label || icon"
    :class="rootClasses"
  >
    <!-- Loading slot (customisable spinner) -->
    <template v-if="$slots.loading" #loading>
      <slot name="loading" />
    </template>

    <!-- Content: icon + label OR slot-only -->
    <template #default>
      <div v-if="hasContent && !iconOnly" class="f-btn__content">
        <q-icon
          v-if="icon"
          :name="icon"
          :class="iconClasses"
          :size="iconSizePx"
        />
        <span v-if="displayLabel" class="f-btn__label" :class="labelClasses">
          {{ displayLabel }}
        </span>
      </div>
      <slot />
    </template>
  </QBtn>
</template>

<script>
import { defineComponent } from 'vue';
// QBtn is imported and registered locally instead of relying on Quasar's
// global registration: the tag then resolves as a component everywhere,
// including the vitest lanes, whose ``isCustomElement`` turns every ``q-*``
// tag into a custom element. A named-slot ``<template #loading>`` under a
// custom element has no codegen node, so the Vue compiler aborts the whole
// module and every spec that transitively imports FellowButton dies at
// transform time. Rendering is unchanged - the same QBtn either way.
import { QBtn } from 'quasar';

const APPEARANCE_LIST = [
  'primary',
  'negative',
  'cancel',
  'flat',
  'secondary',
  'tertiary',
  'negative-tertiary',
  'positive',
  'contrast',
  'alternate',
  'outline',
];

export default defineComponent({
  name: 'FellowButton',

  components: { QBtn },

  props: {
    label: {
      type: String,
      default: '',
    },
    icon: {
      type: String,
      default: '',
    },
    appearance: {
      type: String,
      default: 'primary',
    },
    size: {
      type: String,
      default: 'md',
      validator: (v) => ['xs', 'sm', 'md', 'lg'].includes(v),
    },
    blocked: {
      type: Boolean,
      default: false,
    },
    loading: {
      type: Boolean,
      default: false,
    },
    loadinglabel: {
      type: String,
      default: '',
    },
    to: {
      type: String,
      default: '',
    },
    square: {
      type: Boolean,
      default: false,
    },
    round: {
      type: Boolean,
      default: false,
    },
    dense: {
      type: Boolean,
      default: false,
    },
    invert: {
      type: Boolean,
      default: false,
    },
    smallicon: {
      type: Boolean,
      default: false,
    },
    ariaLabel: {
      type: String,
      default: '',
    },
  },

  computed: {
    normalizedAppearance() {
      const val = (this.appearance || '').toLowerCase();
      return APPEARANCE_LIST.includes(val) ? val : 'primary';
    },

    isFlat() {
      return ['flat', 'tertiary', 'negative-tertiary'].includes(this.normalizedAppearance);
    },

    isOutline() {
      return ['secondary', 'outline'].includes(this.normalizedAppearance);
    },

    isSvgIcon() {
      return this.icon.includes('img:');
    },

    iconOnly() {
      return !this.label && !!this.icon && !this.$slots.default;
    },

    slotOnly() {
      return !this.label && !this.icon && !!this.$slots.default;
    },

    hasContent() {
      return !!(this.icon || this.label || this.loading);
    },

    displayLabel() {
      if (this.loading && this.loadinglabel) return this.loadinglabel;
      return this.label || '';
    },

    iconSizePx() {
      if (this.smallicon) return '14px';
      const sizes = { xs: '14px', sm: '16px', md: '18px', lg: '22px' };
      return sizes[this.size] || '18px';
    },

    rootClasses() {
      const app = this.normalizedAppearance;
      const classes = ['f-btn', `f-btn--${app}`, `f-btn--size-${this.size}`];

      // Only apply icon-only sizing when the caller truly shows only an
      // icon (icon prop without label and without slot content). Passing
      // slot content means custom layout — usually icon + text — which
      // should stay at normal button width.
      if (this.iconOnly) classes.push('f-btn--icon-only');
      if (this.square) classes.push('f-btn--square');
      if (this.round) classes.push('f-btn--round');
      if (this.blocked) classes.push('f-btn--blocked');

      return classes;
    },

    iconClasses() {
      const classes = ['f-btn__icon'];
      if (this.isSvgIcon && this.invert) classes.push('f-btn__icon--invert');
      return classes;
    },

    labelClasses() {
      const classes = [];
      if (this.icon) classes.push('f-btn__label--with-icon');
      return classes;
    },
  },

  methods: {},
});
</script>

<style scoped lang="scss">
// ────────────────────────────────────────
// Size variants
// ────────────────────────────────────────
.f-btn--size-xs {
  min-height: 24px;
  padding: 2px 8px;
  font-size: 0.7rem;
}

.f-btn--size-sm {
  min-height: 30px;
  padding: 4px 12px;
  font-size: 0.78rem;
}

.f-btn--size-md {
  min-height: 36px;
  padding: 6px 16px;
  font-size: 0.85rem;
}

.f-btn--size-lg {
  min-height: 44px;
  padding: 8px 24px;
  font-size: 0.95rem;
}

// ────────────────────────────────────────
// Shape variants
// ────────────────────────────────────────
.f-btn {
  border-radius: 5px;
  font-weight: 500;
  letter-spacing: 0.01em;
  transition: all 0.15s ease;
}

.f-btn--square {
  aspect-ratio: 1 / 1;
  padding: 8px;
  min-width: 0;
}

.f-btn--icon-only:not(.f-btn--square):not(.f-btn--round) {
  min-width: 0;
  padding: 6px 10px;
}

// ────────────────────────────────────────
// Content layout
// ────────────────────────────────────────
.f-btn__content {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  line-height: 1;
}

.f-btn__label {
  white-space: nowrap;
}

.f-btn__icon {
  color: inherit;
}

.f-btn__icon--invert {
  filter: invert(100%);
}

// ────────────────────────────────────────
// Blocked / disabled state
// ────────────────────────────────────────
.f-btn--blocked {
  opacity: 0.45;
  // Quasar's ``q-btn--disable`` sets ``pointer-events: none`` to
  // block clicks — but that also stops the browser from showing
  // ANY cursor on the button (it falls through to the parent's
  // default arrow), so the disabled state was visually invisible.
  // Re-enable pointer events for cursor purposes only; the actual
  // click handler in QBtn checks ``props.disable`` in JS, not CSS,
  // so re-enabling pointer-events doesn't accidentally fire clicks.
  // ``!important`` is needed to win against Quasar's same-
  // specificity ``pointer-events: none`` declaration.
  cursor: not-allowed !important;
  pointer-events: auto !important;
}

// ────────────────────────────────────────
// Appearance: primary (filled blue)
// ────────────────────────────────────────
.f-btn--primary {
  background-color: $primary;
  color: white;
}

// ────────────────────────────────────────
// Appearance: secondary (outlined primary)
// ────────────────────────────────────────
.f-btn--secondary {
  background-color: transparent;
  border: 2px solid var(--primary);
  color: var(--primary);
}

// ────────────────────────────────────────
// Appearance: outline (alias for secondary)
// ────────────────────────────────────────
.f-btn--outline {
  background-color: transparent;
  border: 2px solid var(--primary);
  color: var(--primary);
}

// ────────────────────────────────────────
// Appearance: negative (filled red)
// ────────────────────────────────────────
.f-btn--negative {
  background-color: $negative;
  color: white;
}

// ────────────────────────────────────────
// Appearance: positive (filled green)
// ────────────────────────────────────────
.f-btn--positive {
  background-color: $positive;
  color: white;
}

// ────────────────────────────────────────
// Appearance: cancel (grey)
// ────────────────────────────────────────
.f-btn--cancel {
  background-color: $grey-6;
  color: white;
}

// ────────────────────────────────────────
// Appearance: flat (transparent)
// ────────────────────────────────────────
.f-btn--flat {
  background-color: transparent;
  color: var(--foreground);

  &:hover {
    background-color: var(--accent);
  }
}

// ────────────────────────────────────────
// Appearance: tertiary (flat with primary colour)
// ────────────────────────────────────────
.f-btn--tertiary {
  background-color: transparent;
  color: var(--primary);

  &:hover {
    background-color: color-mix(in srgb, var(--primary) 10%, transparent);
  }
}

// ────────────────────────────────────────
// Appearance: negative-tertiary (flat red text)
// ────────────────────────────────────────
.f-btn--negative-tertiary {
  background-color: transparent;
  color: var(--destructive);

  &:hover {
    background-color: color-mix(in srgb, var(--destructive) 10%, transparent);
  }
}

// ────────────────────────────────────────
// Appearance: contrast (secondary bg)
// ────────────────────────────────────────
.f-btn--contrast {
  background-color: $secondary;
  color: #1a1a1a;
}

// ────────────────────────────────────────
// Appearance: alternate (amber)
// ────────────────────────────────────────
.f-btn--alternate {
  background-color: $amber-14;
  color: white;
}
</style>

<style lang="scss">
// Unscoped: ensure ALL icons inside f-btn inherit text color.
// Covers: Quasar q-icon (:icon prop), slot-based <Icon> (svg), and <img> icons.
.f-btn .q-btn__content {
  color: inherit;

  .q-icon,
  svg {
    color: inherit !important;
    fill: currentColor;
  }
}
</style>
